        CoreLayout layout=new CoreLayout(core.width,core.height,core.depth,facing.getIndex(),cx,cz);BlockPos root=new BlockPos(layout.pivotX(),0,layout.pivotZ());List<VehicleStructure.Cell> rows=new ArrayList<>();
